// Validates basic input requirements
const input = $input.first().json;

// Initialize validation result
const result = {
  isValid: true,
  errors: [],
  originalData: input
};

// Check required fields
if (!input.operation_id) {
  result.isValid = false;
  result.errors.push("Missing operation_id");
}

if (!input.request_id) {
  result.isValid = false;
  result.errors.push("Missing request_id");
}

if (!input.user_data) {
  result.isValid = false;
  result.errors.push("Missing user_data");
}

// Validate username
if (!input.user_data?.username) {
  result.isValid = false;
  result.errors.push("Missing username in user_data");
} else if (!/^[a-zA-Z0-9._-]{3,50}$/.test(input.user_data.username)) {
  result.isValid = false;
  result.errors.push("Invalid username format (must be 3-50 alphanumeric chars, dots, underscores, hyphens)");
}

// Validate email format if provided
if (input.user_data?.email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(input.user_data.email)) {
    result.isValid = false;
    result.errors.push("Invalid email format");
  }
}

// Validate operation_type
const validOperationTypes = [
  "CREATE_USER", "UPDATE_USER", "DELETE_USER",
  "CREATE_ROLE", "UPDATE_ROLE", "DELETE_ROLE",
  "ASSIGN_ROLE", "REVOKE_ROLE"
];
if (!validOperationTypes.includes(input.operation_type)) {
  result.isValid = false;
  result.errors.push(`Invalid operation_type: ${input.operation_type}`);
}

// Validate target_service
const validTargetServices = ["MYSQL", "POSTGRESQL", "ODOO", "LDAP"];
if (!validTargetServices.includes(input.target_service)) {
  result.isValid = false;
  result.errors.push(`Invalid target_service: ${input.target_service}`);
}

return [{ json: result }];

// Apply business rules validation
const input = $input.first().json;
const originalData = input.originalData;

const result = {
  approved: true,
  reason: null,
  validation_id: crypto.randomUUID(),
  modified_data: null,
  metadata: {
    validated_at: new Date().toISOString(),
    validator: "n8n-validation-workflow",
    rules_applied: []
  }
};

// Rule 1: Admin role requires explicit approval (auto-approve for non-admin)
const roles = originalData.user_data?.roles || [];
const hasAdminRole = roles.some(r => 
  r.toLowerCase().includes('admin') || 
  r.toLowerCase().includes('superuser')
);

if (hasAdminRole) {
  result.metadata.rules_applied.push("admin_role_check");
  // For demo purposes, auto-approve but flag it
  result.metadata.admin_role_detected = true;
  // In production, you might set approved = false for manual review
  // result.approved = false;
  // result.reason = "Admin role assignment requires manual approval";
}

// Rule 2: DELETE operations on critical services need extra validation
if (originalData.operation_type === "DELETE_USER" && 
    ["ODOO", "LDAP"].includes(originalData.target_service)) {
  result.metadata.rules_applied.push("critical_delete_check");
  // Auto-approve but log for audit
  result.metadata.critical_operation = true;
}

// Rule 3: Password complexity for CREATE_USER (if password provided)
if (originalData.operation_type === "CREATE_USER" && originalData.user_data?.password) {
  const password = originalData.user_data.password;
  const hasUppercase = /[A-Z]/.test(password);
  const hasLowercase = /[a-z]/.test(password);
  const hasNumber = /[0-9]/.test(password);
  const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(password);
  const isLongEnough = password.length >= 8;

  if (!(hasUppercase && hasLowercase && hasNumber && hasSpecial && isLongEnough)) {
    result.approved = false;
    result.reason = "Password does not meet complexity requirements (min 8 chars, uppercase, lowercase, number, special char)";
    result.metadata.rules_applied.push("password_complexity_failed");
  } else {
    result.metadata.rules_applied.push("password_complexity_passed");
  }
}

// Rule 4: Duplicate check simulation (in production, would query a database)
result.metadata.rules_applied.push("duplicate_check_simulated");

// Copy original data for reference
result.operation_id = originalData.operation_id;
result.request_id = originalData.request_id;

return [{ json: result }];
